/**
 * Merge consumer-supplied presets with built-ins.
 * `replace` true → consumer set wins entirely (no built-ins).
 */
export function resolveFilterPresets(
  consumer: FilterPreset[] | undefined,
  replace: boolean,
): FilterPreset[] {
  if (replace) return consumer ?? [];
  if (!consumer || consumer.length === 0) return BUILT_IN_FILTER_PRESETS;
  // Consumer presets appended after built-ins; ids are not de-duped (consumer's
  // responsibility — id collisions can't happen by accident with built-in names).
  return [...BUILT_IN_FILTER_PRESETS, ...consumer];
}

/**
 * MediaRecorder codec preference chain.
 *
 * Chrome/Edge/Firefox prefer WebM (VP9 → VP8); Safari only supports MP4.
 * Each entry includes the audio codec so the resulting MIME string is
 * directly usable in `new MediaRecorder(stream, { mimeType })`.
 */
export const PREFERRED_RECORDER_MIME_TYPES = [
  "video/webm;codecs=vp9,opus",
  "video/webm;codecs=vp8,opus",
  "video/webm",
  "video/mp4;codecs=avc1.42E01E,mp4a.40.2",
  "video/mp4;codecs=avc1,mp4a",
  "video/mp4",
] as const;

export type RecorderMimeType = (typeof PREFERRED_RECORDER_MIME_TYPES)[number];

/**
 * Picks the highest-preference MIME the current browser supports for
 * MediaRecorder. Returns null when nothing matches (very old browsers).
 */
export function selectRecorderMime(): RecorderMimeType | null {
  if (typeof MediaRecorder === "undefined") return null;
  for (const mime of PREFERRED_RECORDER_MIME_TYPES) {
    try {
      if (MediaRecorder.isTypeSupported(mime)) return mime;
    } catch {
      // Some browsers throw on unknown MIMEs — keep looking.
    }
  }
  return null;
}

/** Extracts the bare container ("webm" or "mp4") for filename hints. */
export function containerFor(mime: string): "webm" | "mp4" | "unknown" {
  if (mime.startsWith("video/webm")) return "webm";
  if (mime.startsWith("video/mp4")) return "mp4";
  return "unknown";
}

import type { ComposerMode } from "../types";

export type ResolvedPresentation = "inline" | "dialog";

/**
 * Resolves the runtime `presentation` mode per description §6.
 *
 * Rules:
 *  - "inline" — render bare in parent layout. No portal/modal/focus-trap.
 *  - "dialog" — wrap in shadcn dialog.
 *  - "auto"   — if `enabledModes` is empty (pure-edit context, no capture
 *               surface), pick "inline". Otherwise pick "dialog". The presence
 *               of `initialSource` does NOT change the rule.
 */
export function resolvePresentation(
  presentation: "inline" | "dialog" | "auto" | undefined,
  enabledModes: readonly ComposerMode[],
): ResolvedPresentation {
  if (presentation === "inline") return "inline";
  if (presentation === "dialog") return "dialog";
  // auto (or undefined, defaults to auto)
  return enabledModes.length === 0 ? "inline" : "dialog";
}

import type { AspectRatio } from "../types";

const ALL_ASPECTS: readonly AspectRatio[] = [
  "9:16",
  "1:1",
  "16:9",
  "4:5",
  "free",
];

/**
 * Crop tool's `cropAspects` default-derivation per description §4 "crop" row:
 *
 *   - If parent `aspect !== "free"` (canvas IS locked):
 *       default cropAspects = [aspect] — crop tool offers sub-region selection
 *       WITHIN the locked aspect only.
 *
 *   - If parent `aspect === "free"` (no canvas lock):
 *       default cropAspects = ["9:16","1:1","16:9","4:5","free"] — full menu.
 *
 *   - If consumer passes `cropAspects` explicitly, that overrides the default.
 */
export function resolveCropAspects(
  aspect: AspectRatio,
  cropAspectsOverride: AspectRatio[] | undefined,
): AspectRatio[] {
  if (cropAspectsOverride !== undefined) return cropAspectsOverride;
  if (aspect === "free") return [...ALL_ASPECTS];
  return [aspect];
}

"use client";

import { useState } from "react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";

export interface ColorSwatchPickerProps {
  value: string;
  presets: string[];
  onChange: (color: string) => void;
  ariaLabel: string;
  triggerClassName?: string;
}

/**
 * Popover color picker — preset swatch grid + free-form hex input.
 *
 * The trigger renders a 28px circle showing the current color.
 * No native <input type="color"> (intentionally — it breaks design-system
 * consistency across OS pickers).
 *
 * F-cross-13 defense: PopoverTrigger renders as its own button without
 * `asChild` — Base UI's PopoverTrigger doesn't accept Slot mergeProps,
 * and the namespaced `radix-ui` package isn't portable across consumers
 * (some have only @radix-ui/react-popover individually). Composing
 * directly through PopoverTrigger works against either shape.
 */
export function ColorSwatchPicker({
  value,
  presets,
  onChange,
  ariaLabel,
  triggerClassName,
}: ColorSwatchPickerProps) {
  const [hexDraft, setHexDraft] = useState(value);
  const [open, setOpen] = useState(false);

  const commitHex = (raw: string) => {
    const trimmed = raw.trim();
    if (/^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(trimmed)) {
      onChange(trimmed);
    }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        aria-label={ariaLabel}
        className={cn(
          "inline-grid place-items-center size-7 rounded-full ring-2 ring-white/40 hover:ring-white transition-shadow",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white",
          triggerClassName,
        )}
        style={{ background: value }}
      >
        <span className="sr-only">{ariaLabel}</span>
      </PopoverTrigger>
      <PopoverContent
        sideOffset={8}
        className="w-56 p-3 bg-popover text-popover-foreground"
      >
        <div className="grid grid-cols-6 gap-2">
          {presets.map((color) => {
            const isActive = color.toLowerCase() === value.toLowerCase();
            return (
              <button
                key={color}
                type="button"
                onClick={() => {
                  onChange(color);
                  setHexDraft(color);
                }}
                aria-label={`Color ${color}`}
                aria-pressed={isActive}
                className={cn(
                  "size-7 rounded-full ring-2 ring-offset-1 ring-offset-popover",
                  isActive ? "ring-foreground" : "ring-transparent",
                )}
                style={{ background: color }}
              />
            );
          })}
        </div>
        <div className="mt-3 flex items-center gap-2">
          <label className="text-xs text-muted-foreground" htmlFor="color-hex">
            Hex
          </label>
          <input
            id="color-hex"
            type="text"
            value={hexDraft}
            onChange={(e) => setHexDraft(e.target.value)}
            onBlur={(e) => commitHex(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                commitHex((e.target as HTMLInputElement).value);
                setOpen(false);
              }
            }}
            placeholder="#ffffff"
            className="flex-1 min-w-0 h-7 rounded-md border border-input bg-background px-2 text-xs font-mono"
          />
        </div>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import type { StoryComposerLabels } from "../types";

export interface DiscardConfirmDialogProps {
  open: boolean;
  labels: Required<StoryComposerLabels>;
  onCancel: () => void;
  onConfirm: () => void;
}

/**
 * Q-P10a guard — confirms before discarding unsaved edits.
 *
 * Mounted unconditionally; the parent owns `open`. Consumers opt out
 * entirely via `confirmOnDiscard: false`.
 */
export function DiscardConfirmDialog({
  open,
  labels,
  onCancel,
  onConfirm,
}: DiscardConfirmDialogProps) {
  return (
    <AlertDialog
      open={open}
      onOpenChange={(next) => {
        if (!next) onCancel();
      }}
    >
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{labels.discardConfirmTitle}</AlertDialogTitle>
          <AlertDialogDescription>
            {labels.discardConfirmBody}
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel onClick={onCancel}>
            {labels.discardCancel}
          </AlertDialogCancel>
          <AlertDialogAction
            onClick={onConfirm}
            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
          >
            {labels.discardConfirm}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

