import { useEffect, useRef } from "react";
import { AlignCenter, AlignLeft, AlignRight, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";
import { cn } from "@/lib/utils";
import { ColorSwatchPicker } from "./color-swatch-picker";
import type {
  FontOption,
  StoryComposerLabels,
  TextOverlay,
} from "../types";

export interface ToolTextInputProps {
  overlay: TextOverlay;
  fonts: FontOption[];
  colorPresets: string[];
  labels: Required<StoryComposerLabels>;
  onChange: (next: TextOverlay) => void;
  onDelete: () => void;
  className?: string;
}

const MIN_FONT_SIZE = 16;
const MAX_FONT_SIZE = 96;

/**
 * Active-text-overlay editor — text input, font, size, color, align.
 * Mounts when there's a selected text overlay.
 */
export function ToolTextInput({
  overlay,
  fonts,
  colorPresets,
  labels,
  onChange,
  onDelete,
  className,
}: ToolTextInputProps) {
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  // Autofocus when a new overlay is selected.
  useEffect(() => {
    textareaRef.current?.focus();
    textareaRef.current?.select();
  }, [overlay.id]);

  const update = (patch: Partial<TextOverlay>) =>
    onChange({ ...overlay, ...patch });

  return (
    <div
      className={cn(
        "flex flex-col gap-3 rounded-2xl bg-black/70 backdrop-blur-md p-3 text-white",
        className,
      )}
    >
      <textarea
        ref={textareaRef}
        value={overlay.text}
        onChange={(e) => update({ text: e.target.value })}
        placeholder={labels.textPlaceholder}
        rows={2}
        className="w-full resize-none rounded-md bg-black/40 border border-white/15 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-white/40"
        style={{ fontFamily: overlay.fontFamily }}
      />

      {/* Font + color + delete */}
      <div className="flex items-center gap-2">
        <label className="sr-only" htmlFor="text-font">
          {labels.textFontFamily}
        </label>
        <select
          id="text-font"
          value={overlay.fontFamily}
          onChange={(e) => update({ fontFamily: e.target.value })}
          className="flex-1 h-8 rounded-md bg-black/40 border border-white/15 px-2 text-xs"
        >
          {fonts.map((font) => (
            <option
              key={font.id}
              value={font.family}
              style={{ fontFamily: font.family }}
            >
              {font.label}
            </option>
          ))}
        </select>

        <ColorSwatchPicker
          value={overlay.fill}
          presets={colorPresets}
          onChange={(color) => update({ fill: color })}
          ariaLabel={labels.drawColor}
        />

        {/* Align toggle */}
        <div className="inline-flex rounded-md bg-black/40 border border-white/15 p-0.5">
          {(["left", "center", "right"] as const).map((align) => (
            <button
              key={align}
              type="button"
              onClick={() => update({ align })}
              aria-label={`${labels.textAlign} ${align}`}
              aria-pressed={overlay.align === align}
              className={cn(
                "p-1 rounded-sm",
                overlay.align === align
                  ? "bg-white text-black"
                  : "text-white/80 hover:text-white",
              )}
            >
              {align === "left" ? (
                <AlignLeft className="size-3.5" />
              ) : align === "center" ? (
                <AlignCenter className="size-3.5" />
              ) : (
                <AlignRight className="size-3.5" />
              )}
            </button>
          ))}
        </div>

        <Button
          variant="ghost"
          size="icon"
          onClick={onDelete}
          aria-label="Delete text"
          className="size-8 text-red-300 hover:bg-red-500/15 hover:text-red-200"
        >
          <Trash2 className="size-4" />
        </Button>
      </div>

      {/* Font size slider */}
      <div className="flex items-center gap-3">
        <span className="text-[10px] uppercase tracking-wider text-white/60 w-10">
          {labels.textFontSize}
        </span>
        <Slider
          value={[overlay.fontSize]}
          min={MIN_FONT_SIZE}
          max={MAX_FONT_SIZE}
          step={1}
          // Radix emits number[]; Base UI number | readonly number[] (F-cross-13)
          onValueChange={(v) =>
            update({ fontSize: typeof v === "number" ? v : (v[0] ?? overlay.fontSize) })
          }
          aria-label={labels.textFontSize}
          className="flex-1"
        />
        <span className="text-xs font-mono tabular-nums w-8 text-right">
          {overlay.fontSize}
        </span>
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent,
} from "react";
import { cn } from "@/lib/utils";
import type { StoryComposerLabels } from "../types";

export interface VideoTrimBarProps {
  /** Source video URL (object URL from a Blob is fine). */
  videoUrl: string;
  /** Trim range in seconds — controlled. */
  startSec: number;
  endSec: number;
  /** Authoritative duration from the source video. */
  durationSec: number;
  /** Number of preview thumbnails to generate (default 8). */
  thumbnailCount?: number;
  labels: Required<StoryComposerLabels>;
  onChange: (next: { startSec: number; endSec: number }) => void;
  className?: string;
}

interface FrameThumb {
  t: number;
  url: string;
}

const MIN_DURATION_SEC = 0.5;

/**
 * Two-handle trim bar with auto-generated frame previews.
 *
 * Thumbnails are produced once on mount by seeking an off-DOM <video>
 * to N evenly-spaced timestamps and snapping each frame to a canvas.
 */
export function VideoTrimBar({
  videoUrl,
  startSec,
  endSec,
  durationSec,
  thumbnailCount = 8,
  labels,
  onChange,
  className,
}: VideoTrimBarProps) {
  const trackRef = useRef<HTMLDivElement | null>(null);
  const [thumbs, setThumbs] = useState<FrameThumb[]>([]);
  const draggingRef = useRef<"start" | "end" | null>(null);

  // ─── Generate frame thumbnails ──────────────────────────────────────
  useEffect(() => {
    let cancelled = false;
    if (!videoUrl || durationSec <= 0) return;

    const video = document.createElement("video");
    video.src = videoUrl;
    video.crossOrigin = "anonymous";
    video.muted = true;
    video.preload = "auto";
    video.playsInline = true;

    const cleanup = () => {
      video.removeAttribute("src");
      video.load();
    };

    const onLoaded = async () => {
      const canvas = document.createElement("canvas");
      const w = 64;
      const h = 96;
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        cleanup();
        return;
      }
      const out: FrameThumb[] = [];
      for (let i = 0; i < thumbnailCount; i++) {
        const t = (i / (thumbnailCount - 1 || 1)) * durationSec;
        await seekTo(video, t);
        if (cancelled) return;
        ctx.drawImage(video, 0, 0, w, h);
        const url = canvas.toDataURL("image/jpeg", 0.6);
        out.push({ t, url });
      }
      if (!cancelled) setThumbs(out);
      cleanup();
    };

    video.addEventListener("loadedmetadata", onLoaded, { once: true });

    return () => {
      cancelled = true;
      video.removeEventListener("loadedmetadata", onLoaded);
      cleanup();
    };
  }, [videoUrl, durationSec, thumbnailCount]);

  // ─── Drag handlers ──────────────────────────────────────────────────
  const positionForX = useCallback(
    (clientX: number): number => {
      const track = trackRef.current;
      if (!track) return 0;
      const rect = track.getBoundingClientRect();
      const ratio = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
      return ratio * durationSec;
    },
    [durationSec],
  );

  const handlePointerDown = useCallback(
    (which: "start" | "end") => (e: PointerEvent<HTMLButtonElement>) => {
      e.currentTarget.setPointerCapture?.(e.pointerId);
      draggingRef.current = which;
    },
    [],
  );

  const handlePointerMove = useCallback(
    (e: PointerEvent<HTMLDivElement>) => {
      if (!draggingRef.current) return;
      const next = positionForX(e.clientX);
      if (draggingRef.current === "start") {
        const clamped = Math.min(next, endSec - MIN_DURATION_SEC);
        onChange({ startSec: Math.max(0, clamped), endSec });
      } else {
        const clamped = Math.max(next, startSec + MIN_DURATION_SEC);
        onChange({ startSec, endSec: Math.min(durationSec, clamped) });
      }
    },
    [endSec, startSec, durationSec, onChange, positionForX],
  );

  const handlePointerUp = useCallback(() => {
    draggingRef.current = null;
  }, []);

  // ─── Render ─────────────────────────────────────────────────────────
  const startPct = durationSec > 0 ? (startSec / durationSec) * 100 : 0;
  const endPct = durationSec > 0 ? (endSec / durationSec) * 100 : 100;

  const placeholders = useMemo(
    () => Array.from({ length: thumbnailCount }, (_, i) => i),
    [thumbnailCount],
  );

  return (
    <div className={cn("flex flex-col gap-2 select-none", className)}>
      <div className="flex items-center justify-between text-[10px] font-mono text-white/70">
        <span>{labels.trimStart}: {startSec.toFixed(1)}s</span>
        <span>{labels.trimEnd}: {endSec.toFixed(1)}s</span>
      </div>
      <div
        ref={trackRef}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        className="relative h-16 rounded-md overflow-hidden bg-black/40 ring-1 ring-white/10"
      >
        {/* Frame strip */}
        <div className="absolute inset-0 flex">
          {(thumbs.length ? thumbs : placeholders).map((entry, i) =>
            typeof entry === "number" ? (
              <div
                key={i}
                className="flex-1 bg-gradient-to-b from-white/5 to-white/10 animate-pulse"
              />
            ) : (
              <div
                key={i}
                className="flex-1 bg-cover bg-center"
                style={{ backgroundImage: `url(${entry.url})` }}
              />
            ),
          )}
        </div>
        {/* Dim out trimmed regions */}
        <div
          className="absolute inset-y-0 left-0 bg-black/60"
          style={{ width: `${startPct}%` }}
          aria-hidden
        />
        <div
          className="absolute inset-y-0 right-0 bg-black/60"
          style={{ width: `${100 - endPct}%` }}
          aria-hidden
        />
        {/* Selection outline */}
        <div
          className="absolute inset-y-0 border-y-2 border-white pointer-events-none"
          style={{ left: `${startPct}%`, right: `${100 - endPct}%` }}
          aria-hidden
        />
        {/* Start handle */}
        <button
          type="button"
          aria-label={labels.trimStart}
          onPointerDown={handlePointerDown("start")}
          className="absolute top-0 bottom-0 w-3 -ml-1.5 grid place-items-center bg-white text-black cursor-ew-resize touch-none"
          style={{ left: `${startPct}%` }}
        >
          <span className="block h-6 w-0.5 bg-black/60" aria-hidden />
        </button>
        {/* End handle */}
        <button
          type="button"
          aria-label={labels.trimEnd}
          onPointerDown={handlePointerDown("end")}
          className="absolute top-0 bottom-0 w-3 -ml-1.5 grid place-items-center bg-white text-black cursor-ew-resize touch-none"
          style={{ left: `${endPct}%` }}
        >
          <span className="block h-6 w-0.5 bg-black/60" aria-hidden />
        </button>
      </div>
    </div>
  );
}

function seekTo(video: HTMLVideoElement, t: number): Promise<void> {
  return new Promise((resolve) => {
    const onSeeked = () => {
      video.removeEventListener("seeked", onSeeked);
      resolve();
    };
    video.addEventListener("seeked", onSeeked, { once: true });
    try {
      video.currentTime = Math.min(t, Math.max(0, video.duration || t));
    } catch {
      video.removeEventListener("seeked", onSeeked);
      resolve();
    }
  });
}

"use client";

import * as React from "react";
import type { ComposerMode, StoryComposerLabels, ValidationError } from "../types";

/**
 * Capture injection seam (P3 S3 — feature-slicing, strategy b: injection
 * surface, R1 VERDICT). Base never statically imports `features/capture/**`
 * — a consumer wires camera capture in by passing `capture={mediaCapture}`
 * (MediaEditorProps.capture) from `@ilinxa/media-editor-capture`. This file
 * owns the context, the extension TYPE, and the surface-props contract the
 * base orchestrator (media-editor.tsx) mounts against — mirroring the
 * renderer-registry pattern used elsewhere in the library.
 */

// ─── Structural mirrors of the capture feature's capture-result shapes ────
// Duplicated here (NOT imported from features/capture/**) so this base file
// carries zero static dependency on the feature folder — the F-S1 inline-copy
// pattern (see cross-procomp-imports precedent). The feature's own
// `CapturedPhoto` / `CapturedVideo` (features/capture/hooks/use-media-capture.ts)
// are kept structurally identical to these so `EditorCamera` type-checks
// as a `CameraSurface` without any cast.

export interface CapturedPhotoLike {
  blob: Blob;
  width: number;
  height: number;
  mimeType: string;
}

export interface CapturedVideoLike {
  blob: Blob;
  durationMs: number;
  mimeType: string;
}

/**
 * Props the base orchestrator passes to whatever camera surface answers the
 * capture extension. Mirrors `EditorCameraProps` (features/capture/parts/
 * editor-camera.tsx) field-for-field — the base mount site passes exactly
 * this shape regardless of which implementation is wired in.
 */
export interface MediaCaptureSurfaceProps {
  /** Composer is open + we should hold a live camera stream. */
  enabled: boolean;
  /** Drives mirror behavior, default facing, and the shutter aria-label. */
  mode: ComposerMode;
  defaultFacing?: "user" | "environment";
  recordAudio?: boolean;
  maxFileSizeMb?: number;
  maxVideoDurationSec?: number;
  captureAspectRatio?: number | null;
  autoAcquireOverride?: boolean;
  labels: Required<StoryComposerLabels>;
  onPhoto: (photo: CapturedPhotoLike) => void;
  onVideo: (video: CapturedVideoLike) => void;
  /** Loads an image / video file picked from the gallery into the editor. */
  onGalleryFile: (file: File) => void;
  onValidationError?: (error: ValidationError) => void;
  onPermissionDenied?: () => void;
  renderPermissionDenied?: (ctx: {
    retry: () => void;
    usePicker: () => void;
  }) => React.ReactNode;
}

export interface MediaCaptureExtensionContextValue {
  /**
   * The camera surface component to mount when the editor is in the capture
   * stage with a photo/video mode active. No further capture-state
   * accessors are exposed today — capture's own state (permissions, live
   * stream, recording) lives inside the surface component itself, so there's
   * nothing else for the orchestrator to read.
   */
  CameraSurface: React.ComponentType<MediaCaptureSurfaceProps>;
}

export const MediaCaptureExtensionContext =
  React.createContext<MediaCaptureExtensionContextValue | null>(null);

/** Orchestrator-internal read. Null when no `capture` extension is wired. */
export function useCaptureExtensionOptional(): MediaCaptureExtensionContextValue | null {
  return React.useContext(MediaCaptureExtensionContext);
}

/**
 * Public extension contract a consumer installs to enable camera capture.
 * `@ilinxa/media-editor-capture` ships `mediaCapture: MediaCaptureExtension`
 * — pass it straight through: `<MediaEditor capture={mediaCapture} />`.
 * Custom/alternative capture implementations can supply their own `Provider`
 * as long as it renders `MediaCaptureExtensionContext.Provider` with a
 * `CameraSurface` matching `MediaCaptureSurfaceProps`.
 */
export type MediaCaptureExtension = {
  Provider: React.ComponentType<{ children: React.ReactNode }>;
};

import type { ValidationError } from "../types";

/**
 * Gallery/file-intake validation — type + size check. Generic (not
 * camera-specific): lives in BASE so the file/gallery intake surface works
 * with the capture feature slice absent (P3 S3 — the pure-CAPTURE files
 * moved to `features/capture/`, but picking a file off disk isn't a capture
 * concern). Used by the base file-intake surface (media-editor.tsx) AND by
 * `features/capture/parts/editor-camera.tsx`'s gallery button — the feature
 * imports this DIRECTLY (relative into base), never through the barrel.
 */
export function validateGalleryFile(
  file: File,
  maxFileSizeMb: number,
): ValidationError | null {
  if (!file.type.startsWith("image/") && !file.type.startsWith("video/")) {
    return {
      kind: "unsupported-type",
      message: `Unsupported file type: ${file.type || "unknown"}`,
      file,
    };
  }
  const bytes = file.size;
  const maxBytes = maxFileSizeMb * 1024 * 1024;
  if (bytes > maxBytes) {
    return {
      kind: "file-too-large",
      message: `File is ${(bytes / 1024 / 1024).toFixed(1)} MB — maximum is ${maxFileSizeMb} MB`,
      file,
    };
  }
  return null;
}

// Local default-export wrapper so `React.lazy(() => import("./lazy-editor-canvas"))`
// has a target — `EditorCanvas` itself is a named export. Same-folder
// (intra-component): this carries none of the cross-procomp rewriter hazards
// the media-library `lazy-code-block.tsx` / `lazy-markdown-editor.tsx`
// wrappers document (no category segment to mangle, no other registry item
// involved) — it exists purely for the `React.lazy(...)` default-export
// contract. Compound-component-structure rule: the konva canvas is the
// heavy dep (konva + react-konva) every consumer pulls in, so it gets the
// mandated lazy boundary even though (unlike media-library's viewers) it
// isn't itself droppable — the win here is deferring the konva chunk off
// the editor's initial paint (capture stage / text-only mode never need it).
export { EditorCanvas as default } from "./editor-canvas";
